import{_ as o,C as s,o as i,c as n,j as r,a as t,G as l,a2 as d}from"./chunks/framework.BgSoyxN5.js";const y=JSON.parse('{"title":"TickerForge Ambassador Program | Recurring Referral Rewards","description":"Recurring 20% referral rewards for people who introduce TickerForge to investors and finance communities. Reward structure, levels, attribution rules, and payout mechanics.","frontmatter":{"title":"TickerForge Ambassador Program | Recurring Referral Rewards","description":"Recurring 20% referral rewards for people who introduce TickerForge to investors and finance communities. Reward structure, levels, attribution rules, and payout mechanics."},"headers":[],"relativePath":"ambassador.md","filePath":"ambassador.md","lastUpdated":1786862598000}'),h={name:"ambassador.md"};function c(u,e,p,m,g,f){const a=s("TickerForgeComplianceDisclaimer");return i(),n("div",null,[e[0]||(e[0]=r("h1",{id:"tickerforge-ambassador-program",tabindex:"-1"},[t("TickerForge Ambassador Program "),r("a",{class:"header-anchor",href:"#tickerforge-ambassador-program","aria-label":'Permalink to "TickerForge Ambassador Program"'},"​")],-1)),e[1]||(e[1]=r("p",null,"The Ambassador Program is for people who already talk about research methods, portfolio risk, and how they check a company before acting — analysts, finance creators, community moderators, and long-term users who recommend the tools they actually use.",-1)),e[2]||(e[2]=r("p",null,[t("You share a personal referral link. When someone who arrived through it activates a paid plan, you receive "),r("strong",null,"20% of that subscription every month"),t(" for as long as they stay subscribed. There is no cap on the number of referrals or on monthly rewards.")],-1)),l(a),e[3]||(e[3]=d('<h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li><strong>Get your referral link.</strong> Open the TickerForge bot in Telegram, go to <em>Ambassador Program</em>, and copy your personal link.</li><li><strong>Share it where it belongs.</strong> Posts, newsletters, community threads, comparison content — anywhere your audience is already discussing research and portfolio decisions.</li><li><strong>Earn monthly.</strong> Every referred user on a paid plan generates a recurring reward while their subscription stays active.</li></ol><p>Attribution is first-touch and permanent: once a user is bound to your link, they stay attributed to you. A user who already belongs to another ambassador is never re-attributed.</p><h2 id="reward-structure" tabindex="-1">Reward Structure <a class="header-anchor" href="#reward-structure" aria-label="Permalink to &quot;Reward Structure&quot;">​</a></h2><p>Rewards are 20% of the referred user&#39;s subscription, recalculated every month against their current plan. Plans are charged in Telegram Stars; USD figures are references from the <a href="/pricing">pricing page</a>, not a separate price list.</p><table tabindex="0"><thead><tr><th>Referred user&#39;s plan</th><th>Plan price</th><th>Your recurring reward</th></tr></thead><tbody><tr><td>Early Access</td><td>700 Stars / month (price-locked 12 months)</td><td><strong>140 Stars / month</strong> (~$2.20 reference)</td></tr><tr><td>Standard</td><td>1,200 Stars / month (~$19 reference)</td><td><strong>240 Stars / month</strong> (~$3.80 reference)</td></tr><tr><td>Pro</td><td>2,000 Stars / month (~$39 reference)</td><td><strong>400 Stars / month</strong> (~$7.80 reference)</td></tr></tbody></table><p>In addition:</p><ul><li><strong>1 free month of Standard</strong> for every 5 paying referrals;</li><li>no limit on the number of referrals;</li><li>no limit on total monthly rewards;</li><li>rewards stop when a referred subscription lapses and resume if it is reactivated.</li></ul><h2 id="example-calculations" tabindex="-1">Example Calculations <a class="header-anchor" href="#example-calculations" aria-label="Permalink to &quot;Example Calculations&quot;">​</a></h2><p>The figures below are arithmetic on current list prices, shown so the structure is transparent. They are illustrations, not a forecast of what you will earn — actual rewards depend on how many referred users hold an active paid plan in a given month.</p><p><strong>All referrals on Standard (240 Stars each):</strong></p><table tabindex="0"><thead><tr><th>Active paying referrals</th><th>Monthly reward</th></tr></thead><tbody><tr><td>5</td><td>1,200 Stars (~$19)</td></tr><tr><td>10</td><td>2,400 Stars (~$38)</td></tr><tr><td>25</td><td>6,000 Stars (~$95)</td></tr><tr><td>50</td><td>12,000 Stars (~$190)</td></tr><tr><td>100</td><td>24,000 Stars (~$380)</td></tr></tbody></table><p><strong>Mixed base, closer to a real audience:</strong> 20 Standard + 5 Pro + 10 Early Access referrals → 20 × 240 + 5 × 400 + 10 × 140 = <strong>8,200 Stars / month</strong> (~$137 reference), recurring while those subscriptions stay active.</p><h2 id="ambassador-levels" tabindex="-1">Ambassador Levels <a class="header-anchor" href="#ambassador-levels" aria-label="Permalink to &quot;Ambassador Levels&quot;">​</a></h2><p>Your level is derived from the number of <strong>active paying referrals</strong> in the current month. The reward percentage is the same at every level — levels add access and recognition, not a higher rate.</p><table tabindex="0"><thead><tr><th>Level</th><th>Active paying referrals</th><th>What it adds</th></tr></thead><tbody><tr><td>Bronze</td><td>1–4</td><td>20% recurring rewards, Bronze badge in your profile</td></tr><tr><td>Silver</td><td>5–19</td><td>+1 free month of Standard per 5 referrals, priority support</td></tr><tr><td>Gold</td><td>20–49</td><td>Monthly insights report (macro, sectors, signals context)</td></tr><tr><td>Platinum</td><td>50–99</td><td>Extended insights, &quot;TickerForge Advisor&quot; badge, early access to new features</td></tr><tr><td>Elite</td><td>100+</td><td>All Platinum benefits, monthly personal portfolio analysis, partner spotlight, direct line to the founder</td></tr></tbody></table><p>Each level includes everything from the levels below it. Check your current level and referral count with <strong>Ambassador Levels</strong> in the bot.</p><h2 id="payouts" tabindex="-1">Payouts <a class="header-anchor" href="#payouts" aria-label="Permalink to &quot;Payouts&quot;">​</a></h2><ul><li>Rewards are calculated per calendar month from the paid plans held by your referred users during that month.</li><li>The amount shown in <strong>My Monthly Earnings</strong> in the bot is an estimate based on current subscription state, not a settled invoice.</li><li>Payout details are confirmed individually once you have your first paying referrals. Ask through the bot or <a href="/contact">contact</a> if you need the terms before you start.</li></ul><h2 id="what-we-ask" tabindex="-1">What We Ask <a class="header-anchor" href="#what-we-ask" aria-label="Permalink to &quot;What We Ask&quot;">​</a></h2><p>The program is open, but the positioning has to hold. When you promote TickerForge:</p><ul><li>present it as research and decision-support software, not as advice, signals, or a way to make money on the markets;</li><li>disclose that your link is affiliate-supported, per the rules of the platform you post on;</li><li>do not promise investment returns, guaranteed outcomes, or specific entry and exit points on TickerForge&#39;s behalf;</li><li>do not use paid search or ads on TickerForge brand terms without written agreement;</li><li>keep it honest: describe what the product actually does — stock checks, portfolio diagnostics, concentration and exposure review, market context, alerts.</li></ul><p>Referrals from spam, incentivized sign-ups, self-referral, or fake accounts do not count and can end participation.</p><h2 id="what-this-program-is-not" tabindex="-1">What This Program Is Not <a class="header-anchor" href="#what-this-program-is-not" aria-label="Permalink to &quot;What This Program Is Not&quot;">​</a></h2><p>The Ambassador Program is a referral arrangement for software subscriptions. It is not:</p><ul><li>revenue sharing on investment results;</li><li>a promise that referred users will subscribe or stay subscribed;</li><li>an advisory, brokerage, or introducing-broker relationship;</li><li>a licence to present yourself as a TickerForge employee or representative.</li></ul><p>TickerForge is educational decision-support software. It does not provide personalized investment advice, execute trades, or guarantee outcomes — and neither does anything you say about it on our behalf.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><ol><li>Open TickerForge in Telegram.</li><li>Go to <strong>Ambassador Program</strong>.</li><li>Copy your personal referral link.</li><li>Share it where your audience already discusses research and portfolio decisions.</li></ol><p>If you run a channel, newsletter, or community and want a structured collaboration rather than a personal link, see the <a href="/partners">Partner Program</a> — a partner pilot and the Ambassador Program run in parallel, and the same audience can arrive through a tracked pilot link and subscribe through your referral link.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/pricing">TickerForge Pricing</a></li><li><a href="/partners">Partner Program</a></li><li><a href="/partners/requirements">Partner requirements</a></li><li><a href="/import-portfolio">Portfolio Health Check</a></li><li><a href="/stock-widget">Stock Check Widget</a></li><li><a href="/terms">Terms</a></li></ul>',32))])}const k=o(h,[["render",c]]);export{y as __pageData,k as default};
